/** Small, optional disagreements between existing residents. Selection is seeded;
 * choices use the ordinary encounter history, purse and personal relationships. */
const pair = (systemId, bodyId, people) => ({ systemId, bodyId, people });
const places = {
  kettle: pair('hearth', 'kettle', ['len-vale', 'silas-voss']),
  morrow: pair('hearth', 'morrow', ['mara-reed', 'ada-finch']),
  weighhouse: pair('brindle', 'weighhouse', ['nadi-vale', 'earth-tess']),
  ledger: pair('meridian', 'ledger', ['commissioner-ryn', 'earth-ryn']),
  bastion: pair('nacre', 'bastion', ['doctor-sef', 'earth-sef']),
  listening: pair('vesper', 'listening', ['tiva', 'earth-jun']),
  glimmer: pair('voltage', 'glimmer', ['voltage-juno', 'voltage-asa'])
};
const option = (id, label, text, result, trust = {}, credits = 0, reactions = {}) => ({ id, label, text, result, trust, credits, reactions });
const scene = (place, variant, slug, title, text, choices) => {
  const at = places[place], id = `people:${place}:${slug}`;
  return { id, title, tag: 'LOCAL PEOPLE', mode: 'person', once: true, peopleEvent: { group: place, variant, participants: at.people },
    conditions: { systemId: at.systemId, locationId: at.bodyId }, text,
    choices: choices.map(({ trust, credits, reactions, ...value }) => ({ ...value,
      ...(credits < 0 ? { conditions: { credits: -credits } } : {}),
      effects: { ...(credits ? { credits } : {}), flags: [`${id}:${value.id}`] }, peopleTrust: trust, peopleReactions: reactions })) };
};

